table(['Stad','Fisk före→efter','Mat före→efter','Civil netto före→efter','Placeringar före→efter'],[[c['name'],f(c['old_rates'].get('fish',0))+'→'+f(c['rates']['fish']),f(sum(c['old_rates'].get(g,0) for g in food))+'→'+f(sum(c['rates'][g] for g in food)),f(sum(c['old_rates'].get(g,0) for g in food)-c['old_population']*.005)+'→'+f(sum(c['rates'][g] for g in food)-c['civil_need']),str(c['old_placements'])+'→'+str(len(next(x for x in s['cities'] if x['id']==c['id'])['placements']))] for c in cities]), '',
